import { createHash } from 'node:crypto';
import { describe, expect, it } from 'vitest';
import { parseRealtekCvimgHeader } from '../src/realtek-image.js';

/**
 * Complete outputs of the ORIGINAL vendor-authored cvimg.c (pinned mirror, unpatched; built with
 * -DCOMPACT_FILENAME_BUFFER -DHOME_GATEWAY -DCONFIG_RTL_8196C plus -DDEFFILEMODE=0666 for musl) over inert payloads,
 * generated in a network-none read-only container and never executed. `worker` rows were generated by this task's
 * worker; `coordinator` rows by the campaign coordinator. Hashes are of the exact bytes. The trailing two bytes are
 * the producer's checksum, which the parser must report as located and NOT verified.
 */
const GENERATED = [
  [
    'worker',
    'linux p0 80500000 30000',
    'Y3M2Y4BQAAAAAwAAAAAAAgAA',
    '24e6cf78834b41e824bd6cb867c839bdce68d2fbd62aba6108a70b31949ffc73',
    'cs6c',
    0x80500000,
    0x30000,
    2,
  ],
  [
    'worker',
    'linux-ro p1 80500000 30000',
    'Y3I2Y4BQAAAAAwAAAAAABAcA+QA=',
    '9dfc1f347cc988d7e9144bf191b36df81ab10d6b80bf5d7beda7e47233ef8e7a',
    'cr6c',
    0x80500000,
    0x30000,
    4,
  ],
  [
    'worker',
    'linux p5 80500000 30000',
    'Y3M2Y4BQAAAAAwAAAAAACAcmRWSDADB2',
    '1ccbe37ad5552c245ad46dc1ad7c029d776447be8f4a632dbf5c71d9bd8b495a',
    'cs6c',
    0x80500000,
    0x30000,
    8,
  ],
  [
    'worker',
    'linux-ro p6 80500000 30000',
    'Y3I2Y4BQAAAAAwAAAAAACAcmRWSDoi/U',
    '03c88c98dabed2c148bd2ec04e6ca1d53fefbd98702e3c81ac72ec2fb75f0938',
    'cr6c',
    0x80500000,
    0x30000,
    8,
  ],
  [
    'worker',
    'linux-ro p3 ffffffff ffffffff',
    'Y3I2Y///////////AAAABgcmRQCz2g==',
    '9025bad749f1c3df1a5210c9f8ffb458aedbde5d253bb88fdbaad763c2c0ff21',
    'cr6c',
    0xffffffff,
    0xffffffff,
    6,
  ],
  [
    'coordinator',
    'linux p1 1 80000000',
    'Y3M2YwAAAAGAAAAAAAAABAEA/wA=',
    '0e6ccb61c8f3c70ca7e8ec2455b9056ca2bd06d07131d36658955822038e5f8e',
    'cs6c',
    1,
    0x80000000,
    4,
  ],
  [
    'coordinator',
    'linux canary [1..5] 80500000 30000',
    'Y3M2Y4BQAAAAAwAAAAAACAECAwQFAPb6',
    'b85e4057e7778ae5df98309c8291adca4781114af42e522c60a632c5510fff23',
    'cs6c',
    0x80500000,
    0x30000,
    8,
  ],
] as const;
/** The same generator's `signature` option writing `csys`: a real producer output the subset still refuses. */
const GENERATED_CSYS = 'Y3N5c4BQAAAAAwAAAAAACAcmRWSDADB2';

function fromBase64(b64: string): Uint8Array {
  return new Uint8Array(Buffer.from(b64, 'base64'));
}

/**
 * Further fixtures are assembled HERE from the field facts in docs/REALTEK-CVIMG-20261108.md (packed 16-byte IMG_HEADER_T,
 * DWORD_SWAP-written words, len = payload + 2-byte checksum rounded up to even) to reach shapes no generator run
 * emits (truncations, bad lengths, wrong byte order). Their checksum bytes are arbitrary on purpose.
 */
function ascii(s: string): number[] {
  return [...s].map((c) => c.charCodeAt(0));
}
function be32(v: number): number[] {
  return [(v >>> 24) & 0xff, (v >>> 16) & 0xff, (v >>> 8) & 0xff, v & 0xff];
}
function cvimg(signature: string, payloadLength: number, startAddr = 0x80500000, burnAddr = 0x30000): Uint8Array {
  const len = payloadLength + 2 + (payloadLength % 2);
  const out = new Uint8Array(16 + len);
  out.set([...ascii(signature), ...be32(startAddr), ...be32(burnAddr), ...be32(len)]);
  for (let i = 0; i < payloadLength; i++) out[16 + i] = (i * 7 + 3) & 0xff;
  out[16 + len - 2] = 0xde;
  out[16 + len - 1] = 0xad;
  return out;
}

describe('parseRealtekCvimgHeader', () => {
  it.each(GENERATED)('matches the actual generator output (%s: %s)', (_by, _args, b64, sha, sig, start, burn, len) => {
    const bytes = fromBase64(b64);
    expect(createHash('sha256').update(bytes).digest('hex')).toBe(sha);
    expect(parseRealtekCvimgHeader(bytes)).toEqual({
      valid: true,
      signature: sig,
      producerOption: sig === 'cs6c' ? 'linux' : 'linux-ro',
      startAddress: start,
      burnAddress: burn,
      declaredLength: len,
      totalSize: bytes.length,
      bodyLength: len - 2,
      checksum: { width: 2, offset: bytes.length - 2, summedStart: 16, summedEnd: bytes.length, verified: false },
    });
  });

  it("refuses the generator's own csys output, which this subset leaves unsupported", () => {
    expect(parseRealtekCvimgHeader(fromBase64(GENERATED_CSYS))).toMatchObject({
      valid: false,
      reason: expect.stringMatching(/csys.*unsupported/),
    });
  });

  it('decodes the linux and linux-ro signatures with big-endian fields and the checksum NOT verified', () => {
    expect(parseRealtekCvimgHeader(cvimg('cs6c', 5))).toEqual({
      valid: true,
      signature: 'cs6c',
      producerOption: 'linux',
      startAddress: 0x80500000,
      burnAddress: 0x30000,
      declaredLength: 8,
      totalSize: 24,
      bodyLength: 6,
      checksum: { width: 2, offset: 22, summedStart: 16, summedEnd: 24, verified: false },
    });
    expect(parseRealtekCvimgHeader(cvimg('cr6c', 4))).toMatchObject({
      valid: true,
      signature: 'cr6c',
      producerOption: 'linux-ro',
      declaredLength: 6,
      totalSize: 22,
      checksum: { offset: 20, verified: false },
    });
  });

  it('accepts the empty-input minimum (len 2), any declared addresses, and ignores the checksum value', () => {
    const empty = cvimg('cs6c', 0, 0, 0);
    expect(empty.length).toBe(18);
    expect(parseRealtekCvimgHeader(empty)).toMatchObject({
      valid: true,
      declaredLength: 2,
      bodyLength: 0,
      startAddress: 0,
      burnAddress: 0,
      checksum: { offset: 16, verified: false },
    });
    const high = cvimg('cs6c', 1, 0xffffffff, 0xffffffff);
    expect(parseRealtekCvimgHeader(high)).toMatchObject({ valid: true, startAddress: 0xffffffff, declaredLength: 4 });
    const flipped = cvimg('cs6c', 3);
    flipped[16 + 4 - 2] ^= 0xff;
    flipped[16] ^= 0xff;
    expect(parseRealtekCvimgHeader(flipped)).toMatchObject({ valid: true, checksum: { verified: false } });
  });

  it('reads at an embedded offset inside a non-zero Uint8Array view and leaves trailing bytes unconstrained', () => {
    const image = cvimg('cr6c', 9);
    const backing = new Uint8Array(image.length + 64).fill(0x5a);
    backing.set(image, 21);
    const view = backing.subarray(8);
    expect(parseRealtekCvimgHeader(view, 13)).toEqual(parseRealtekCvimgHeader(image));
    expect(parseRealtekCvimgHeader(view, 13)).toMatchObject({ valid: true, totalSize: 16 + 12 });
  });

  it('rejects truncated headers and declared regions that exceed the remaining bytes', () => {
    const image = cvimg('cs6c', 10);
    for (let length = 0; length < image.length; length++) {
      expect(parseRealtekCvimgHeader(image.subarray(0, length)), `length ${length}`).toMatchObject({ valid: false });
    }
    expect(parseRealtekCvimgHeader(image)).toMatchObject({ valid: true });
    const huge = cvimg('cs6c', 2);
    huge.set(be32(0xfffffffe), 12);
    expect(parseRealtekCvimgHeader(huge)).toMatchObject({
      valid: false,
      reason: expect.stringMatching(/exceeds the remaining/),
    });
  });

  it('rejects lengths the ordinary producer path cannot write: zero, below the checksum, and odd', () => {
    for (const len of [0, 1, 3, 7]) {
      const image = cvimg('cs6c', 10);
      image.set(be32(len), 12);
      expect(parseRealtekCvimgHeader(image), `len ${len}`).toMatchObject({ valid: false });
    }
  });

  it('rejects little-endian fields that only fit when read with the wrong byte order', () => {
    const image = cvimg('cs6c', 4);
    image.set([6, 0, 0, 0], 12);
    expect(parseRealtekCvimgHeader(image)).toMatchObject({ valid: false });
  });

  it('refuses every other signature, including csys/csro and other cvimg options, and bad offsets', () => {
    for (const sig of ['csys', 'csro', 'CSYS', 'cs6b', 'cr6b', 'r6cr', 'boot', 'root', 'allp', 'Cs6c', 'cs6C']) {
      expect(parseRealtekCvimgHeader(cvimg(sig, 4)), sig).toMatchObject({ valid: false });
    }
    expect(parseRealtekCvimgHeader(cvimg('csys', 4))).toMatchObject({ reason: expect.stringMatching(/unsupported/) });
    const image = cvimg('cs6c', 4);
    for (const off of [-1, 1.5, Number.NaN, image.length + 1, Number.MAX_SAFE_INTEGER + 1]) {
      expect(parseRealtekCvimgHeader(image, off), String(off)).toMatchObject({ valid: false });
    }
    expect(parseRealtekCvimgHeader(image, image.length)).toMatchObject({ valid: false });
  });
});
